const raw = $input.first().json.output;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;

const candidates = parsed.candidates || [];

// لو مفيش recommendation جاهزة من الـ AI، رتب المرشحين حسب match_score واختار الأعلى
let strongestIds = [];
if (parsed.recommendation && Array.isArray(parsed.recommendation.strongest_candidates)) {
  strongestIds = parsed.recommendation.strongest_candidates;
} else if (parsed.best_match_id) {
  strongestIds = [parsed.best_match_id];
} else {
  const sorted = [...candidates].sort((a, b) => (b.match_score || 0) - (a.match_score || 0));
  if (sorted.length > 0) strongestIds = [sorted[0].candidate_id];
}

const results = [];

strongestIds.forEach(id => {
  const c = candidates.find(cand => cand.candidate_id === id);
  if (!c) return;

  const ev = c.evaluation || {};
  const mustMet = (ev.must_have_met && ev.must_have_met.length) ? ev.must_have_met.join('، ') : 'لا يوجد';
  const mustMissing = (ev.must_have_missing && ev.must_have_missing.length) ? ev.must_have_missing.join('، ') : 'لا يوجد';
  const niceMet = (ev.nice_to_have_met && ev.nice_to_have_met.length) ? ev.nice_to_have_met.join('، ') : 'لا يوجد';

  const experience = c.total_years_experience || c.years_of_experience || 'Not specified';

  const text =
`✅ تم إيجاد ماتش مناسب للوظيفة: ${parsed.job_title || 'Not specified'}

👤 الاسم: ${c.full_name || 'Not specified'}
🎓 التعليم: ${c.education || 'Not specified'}
🕒 سنوات الخبرة: ${experience}
📊 نسبة التطابق: ${c.match_score !== undefined ? c.match_score : 'Not specified'}%

✅ المتطلبات الأساسية المتحققة: ${mustMet}
⚠️ المتطلبات الأساسية الناقصة: ${mustMissing}
➕ مميزات إضافية متحققة: ${niceMet}

📝 ${c.score_explanation || ''}

هل تريد استكمال الإجراءات واستلام السيرة الذاتية وبيانات التواصل؟`;

  results.push({
    json: {
      message: text,
      candidate_id: c.candidate_id,
      full_name: c.full_name
    }
  });
});

return results;
